import { useMemo } from 'react';
import { useIntl } from 'react-intl';

import { BasicContainer } from 'components';

import { PHI_OVERVIEW_BEER_EVOLUTION_TITLE_I18N_ID } from '../../../../constants';
import type { BeerEvolutionBreakdownData } from '../../../../types';
import { StyledBeerEvolutionInnerCard } from './BeerEvolutionBreakdownSection.styles';
import {
  buildBeerEvolutionBrandAvatars,
  computeBeerEvolutionIsEmpty,
  hasAlignedBeerEvolutionChartData,
  mapWaterfallLabels,
  resolveBeerEvolutionTestId,
} from './beerEvolutionBreakdownSection.utils';
import { BeerEvolutionChartContent } from './BeerEvolutionChartContent';
import { BeerEvolutionEmbeddedSection } from './BeerEvolutionEmbeddedSection';

const SECTION_LAYOUT = {
  border: 'small' as const,
  shadow: 'small' as const,
  bodyPadding: false,
  headerPadding: 'none' as const,
  borderRadius: 'large' as const,
  background: '#F9F9F9',
  bodyStyle: {
    boxSizing: 'border-box' as const,
    padding: '20px',
    gap: '16px',
  },
};

export interface BeerEvolutionBreakdownSectionProps {
  data?: BeerEvolutionBreakdownData | null;
  loading?: boolean;
  error?: boolean;
  empty?: boolean;
  stateMessage?: { title: string; description: string };
  dataTestId?: string;
  /** Renders inside Global PHI Performance (PHI Overtime subtitle style). */
  embedded?: boolean;
}

export const BeerEvolutionBreakdownSection = ({
  data,
  loading = false,
  error = false,
  empty = false,
  stateMessage,
  dataTestId,
  embedded = false,
}: BeerEvolutionBreakdownSectionProps) => {
  const { formatMessage } = useIntl();

  const title = formatMessage({
    id: PHI_OVERVIEW_BEER_EVOLUTION_TITLE_I18N_ID,
  });

  const chartValues = data?.values ?? data?.data ?? [];
  const chartLabels = useMemo(() => data?.labels ?? [], [data?.labels]);
  const waterfallLabels = useMemo(
    () => mapWaterfallLabels(chartLabels),
    [chartLabels],
  );
  const hasAlignedChartData = useMemo(
    () =>
      hasAlignedBeerEvolutionChartData(
        data,
        chartLabels.length,
        chartValues.length,
      ),
    [chartLabels.length, chartValues.length, data],
  );
  const isEmpty = computeBeerEvolutionIsEmpty(
    empty,
    data,
    chartLabels.length,
    chartValues.length,
    hasAlignedChartData,
  );
  const brandAvatarData = useMemo(
    () => buildBeerEvolutionBrandAvatars(data, chartLabels),
    [chartLabels, data],
  );

  const chartContent = (
    <BeerEvolutionChartContent
      data={data}
      loading={loading}
      error={error}
      isEmpty={isEmpty}
      stateMessage={stateMessage}
      dataTestId={dataTestId}
      chartValues={chartValues}
      chartLabelsLength={chartLabels.length}
      waterfallLabels={waterfallLabels}
      brandAvatarData={brandAvatarData}
    />
  );

  if (embedded) {
    return (
      <BeerEvolutionEmbeddedSection title={title} dataTestId={dataTestId}>
        {chartContent}
      </BeerEvolutionEmbeddedSection>
    );
  }

  return (
    <BasicContainer
      header={{ title, titleSize: 'H1' }}
      layout={SECTION_LAYOUT}
      fullWidth
      dataTestId={dataTestId ?? 'beer-evolution-breakdown-section'}
    >
      <StyledBeerEvolutionInnerCard
        $loading={loading}
        data-testid={resolveBeerEvolutionTestId(
          dataTestId,
          'inner-card',
          'beer-evolution-breakdown-inner-card',
        )}
      >
        {chartContent}
      </StyledBeerEvolutionInnerCard>
    </BasicContainer>
  );
};
